package com.student.model;
public class Mark { private int markId,studentId,courseId; private String studentName,courseName,remarks; private double marks,maxMarks; public int getMarkId(){return markId;} public void setMarkId(int v){markId=v;} public int getStudentId(){return studentId;} public void setStudentId(int v){studentId=v;} public int getCourseId(){return courseId;} public void setCourseId(int v){courseId=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getCourseName(){return courseName;} public void setCourseName(String v){courseName=v;} public String getRemarks(){return remarks;} public void setRemarks(String v){remarks=v;} public double getMarks(){return marks;} public void setMarks(double v){marks=v;} public double getMaxMarks(){return maxMarks;} public void setMaxMarks(double v){maxMarks=v;} }
